def _a64_c_name(isa_name: str) -> str:
    """Convert arm64.add.rrr → a64_add_rrr."""
    # Remove 'arm64.' prefix and replace dots with underscores
    stem = isa_name.removeprefix('arm64.')
    return 'a64_' + stem.replace('.', '_')

def _gen_arm64_field_expr(enc, operands: list[OperandInfo]) -> str:
    """Generate C expression for ARM64 bitfield encoding.

    ARM64 encoding is: base_opcode | (field_val << bit_pos) | ...
    Each (field bit_pos width $var) inserts a field.
    enc is an SList whose children are: base_opcode (field ...) ...
    """
    if not enc:
        return '0'

    # enc is an SList — access its children
    elems = enc.children if isinstance(enc, SList) else enc
    if not elems:
        return '0'

    # First element is the base opcode
    base = elems[0]
    if isinstance(base, SAtom) and base.is_number:
        parts = [f'0x{base.int_value:08x}u']
    else:
        parts = ['0u']

    # Build operand name → param name map
    op_map = {}
    for op in operands:
        op_map[op.name] = _c_param_name(op)

    # Remaining elements are field operations
    for elem in elems[1:]:
        if not isinstance(elem, SList):
            continue
        children = elem.children
        if len(children) < 4:
            continue
        head = children[0].value if isinstance(children[0], SAtom) else ''

        if head == 'field':
            # (field bit_pos width $var)
            bit_pos = children[1].int_value if isinstance(children[1], SAtom) else 0
            width = children[2].int_value if isinstance(children[2], SAtom) else 0
            var = children[3].value.lstrip('$') if isinstance(children[3], SAtom) else ''
            param = op_map.get(var, var)
            mask = (1 << width) - 1
            if bit_pos == 0:
                parts.append(f'((uint32_t) {param} & 0x{mask:x})')
            else:
                parts.append(f'(((uint32_t) {param} & 0x{mask:x}) << {bit_pos})')

        elif head == 'field-scaled':
            # (field-scaled bit_pos width $var divisor)
            if len(children) < 5:
                continue
            bit_pos = children[1].int_value if isinstance(children[1], SAtom) else 0
            width = children[2].int_value if isinstance(children[2], SAtom) else 0
            var = children[3].value.lstrip('$') if isinstance(children[3], SAtom) else ''
            divisor = children[4].int_value if isinstance(children[4], SAtom) else 1
            param = op_map.get(var, var)
            mask = (1 << width) - 1
            val_expr = f'((uint32_t) {param} / {divisor})' if divisor > 1 else f'(uint32_t) {param}'
            if bit_pos == 0:
                parts.append(f'({val_expr} & 0x{mask:x})')
            else:
                parts.append(f'(({val_expr} & 0x{mask:x}) << {bit_pos})')

        elif head == 'field-xor':
            # (field-xor bit_pos width $var xor_mask)
            if len(children) < 5:
                continue
            bit_pos = children[1].int_value if isinstance(children[1], SAtom) else 0
            width = children[2].int_value if isinstance(children[2], SAtom) else 0
            var = children[3].value.lstrip('$') if isinstance(children[3], SAtom) else ''
            xor_mask = children[4].int_value if isinstance(children[4], SAtom) else 0
            param = op_map.get(var, var)
            mask = (1 << width) - 1
            val_expr = f'((uint32_t) {param} ^ {xor_mask})'
            if bit_pos == 0:
                parts.append(f'({val_expr} & 0x{mask:x})')
            else:
                parts.append(f'(({val_expr} & 0x{mask:x}) << {bit_pos})')

    return ' | '.join(parts)

def generate_arm64_impl(regclasses: list[RegClass], mcinsns: list[McInsn]) -> str:
    """Generate xm_arm64_gen.c — drop-in replacement for hand-written xm_arm64.c."""
    lines = []
    lines.append('/* AUTO-GENERATED by xisagen — DO NOT EDIT */')
    lines.append('/* Source: xisa/arch/arm64.isa */')
    lines.append('')
    lines.append('#ifdef __aarch64__')
    lines.append('')
    lines.append('#include "xm_arm64.h"')
    lines.append('#include "../base/xchecks.h"')
    lines.append('')

    for insn in mcinsns:
        if insn.name in _A64_NAME_MAP:
            c_name = _A64_NAME_MAP[insn.name]
            if c_name is None:
                continue
        else:
            c_name = _a64_c_name(insn.name)
        operands = extract_operands(insn)

        # Build parameter list
        params = []
        for op in operands:
            type_key = f'{op.kind}:{op.subtype}' if op.subtype else op.kind
            c_type = _A64_PARAM_TYPES.get(type_key, 'int32_t')
            params.append(f'{c_type} {_c_param_name(op)}')

        sig = f'uint32_t {c_name}({", ".join(params)})'
        if not params:
            sig = f'uint32_t {c_name}(void)'

        # Generate encoding expression
        enc_expr = _gen_arm64_field_expr(insn.encoding, operands)

        lines.append(f'/* {insn.name} */')
        lines.append(sig + ' {')
        lines.extend(_gen_riscv64_return_lines(enc_expr))
        lines.append('}')
        lines.append('')

    lines.append('#endif  // __aarch64__')
    lines.append('')
    return '\n'.join(lines)

# ============================================================
# L4a3: RISC-V 64 implementation generator
# ============================================================

_RV64_PARAM_TYPES = {
    'reg:gpr': 'uint8_t',
    'reg:fpr': 'uint8_t',
    'imm:i12': 'int32_t',
    'imm:u20': 'uint32_t',
    'imm:rel12': 'int32_t',
    'imm:rel20': 'int32_t',
}

_RV64_NAME_MAP: dict = {}

def _rv64_auto_name(isa_name: str) -> str:
    """Auto-derive C function name: riscv64.fadd.d -> rv64_fadd_d"""
    return 'rv64_' + isa_name.removeprefix('riscv64.').replace('.', '_')

def _rv64_c_name(isa_name: str) -> str:
    return _RV64_NAME_MAP.get(isa_name, _rv64_auto_name(isa_name))


def _gen_riscv64_field_expr(enc, operands: list['OperandInfo']) -> str:
    """Generate C expression for RISC-V 64 bitfield encoding."""
    if not enc:
        return '0'
    elems = enc.children if isinstance(enc, SList) else enc
    if not elems:
        return '0'

    head = elems[0]
    if isinstance(head, SAtom) and head.is_number:
        return f'0x{head.int_value:08x}u'

    fmt = head.value if isinstance(head, SAtom) else ''
    op_map = {}
    for op in operands:
        op_map[op.name] = _c_param_name(op)

    def _ref(idx):
        if idx < len(elems) and isinstance(elems[idx], SAtom):
            if elems[idx].is_variable:
                var = elems[idx].value.lstrip('$')
                return op_map.get(var, var)
            if elems[idx].is_number:
                return f'0x{elems[idx].int_value:x}u'
        return '0'

    if fmt == 'r-type':
        # (r-type opcode funct3 funct7 rd rs1 rs2)
        opcode, funct3, funct7 = _ref(1), _ref(2), _ref(3)
        rd, rs1, rs2 = _ref(4), _ref(5), _ref(6)
        return (f'{opcode} | ((uint32_t)({rd}) << 7) | ({funct3} << 12) '
                f'| ((uint32_t)({rs1}) << 15) | ((uint32_t)({rs2}) << 20) '
                f'| ({funct7} << 25)')

    elif fmt == 'i-type':
        # (i-type opcode funct3 rd rs1 imm)
        opcode, funct3 = _ref(1), _ref(2)
        rd, rs1, imm = _ref(3), _ref(4), _ref(5)
        return (f'{opcode} | ((uint32_t)({rd}) << 7) | ({funct3} << 12) '
                f'| ((uint32_t)({rs1}) << 15) | ((uint32_t)((int32_t)({imm}) & 0xfff) << 20)')

    elif fmt == 's-type':
        # (s-type opcode funct3 rs1 rs2 imm)
        opcode, funct3 = _ref(1), _ref(2)
        rs1, rs2, imm = _ref(3), _ref(4), _ref(5)
        return (f'(uint32_t)({opcode} | (((int32_t)({imm}) & 0x1f) << 7) | ({funct3} << 12) '
                f'| ((uint32_t)({rs1}) << 15) | ((uint32_t)({rs2}) << 20) '
                f'| (((uint32_t)((int32_t)({imm}) >> 5) & 0x7f) << 25))')

    elif fmt == 'b-type':
        # (b-type opcode funct3 rs1 rs2 imm)
        opcode, funct3 = _ref(1), _ref(2)
        rs1, rs2, imm = _ref(3), _ref(4), _ref(5)
        return (f'(uint32_t)({opcode} '
                f'| ((((int32_t)({imm}) >> 11) & 1) << 7) '
                f'| ((((int32_t)({imm}) >> 1) & 0xf) << 8) '
                f'| ({funct3} << 12) '
                f'| ((uint32_t)({rs1}) << 15) '
                f'| ((uint32_t)({rs2}) << 20) '
                f'| ((((int32_t)({imm}) >> 5) & 0x3f) << 25) '
                f'| ((((int32_t)({imm}) >> 12) & 1u) << 31))')

    elif fmt == 'u-type':
        # (u-type opcode rd imm)
        opcode = _ref(1)
        rd, imm = _ref(2), _ref(3)
        return f'{opcode} | ((uint32_t)({rd}) << 7) | ((uint32_t)({imm}) << 12)'

    elif fmt == 'j-type':
        # (j-type opcode rd imm)
        opcode = _ref(1)
        rd, imm = _ref(2), _ref(3)
        return (f'(uint32_t)({opcode} | ((uint32_t)({rd}) << 7) '
                f'| ((((int32_t)({imm}) >> 12) & 0xff) << 12) '
                f'| ((((int32_t)({imm}) >> 11) & 1) << 20) '
                f'| ((((int32_t)({imm}) >> 1) & 0x3ff) << 21) '
                f'| ((((int32_t)({imm}) >> 20) & 1u) << 31))')

    return '0 /* unknown encoding format */'


def _format_c_casts(expr: str) -> str:
    return (expr.replace('(uint32_t)(', '(uint32_t) (')
            .replace('(int32_t)(', '(int32_t) (')
            .replace('(uint8_t)(', '(uint8_t) (')
            .replace('(int8_t)(', '(int8_t) ('))


def _gen_riscv64_return_lines(expr: str) -> list[str]:
    expr = _format_c_casts(expr)
    if expr.startswith('(uint32_t) (') and expr.endswith(')'):
        expr = expr[len('(uint32_t) ('):-1]
    terms = [term.strip() for term in expr.split(' | ')]
    if len(terms) <= 1:
        return [f'    return {terms[0]};']
    lines = [f'    uint32_t insn = {terms[0]};']
    for term in terms[1:]:
        lines.append(f'    insn |= {term};')
    lines.append('    return insn;')
    return lines


def generate_riscv64_impl(regclasses: list['RegClass'], mcinsns: list['McInsn']) -> str:
    """Generate xm_riscv64_gen.c — RISC-V 64 instruction encoder."""
    lines = []
    lines.append('/* AUTO-GENERATED by xisagen — DO NOT EDIT */')
    lines.append('/* Source: xisa/arch/riscv64.isa */')
    lines.append('')
    lines.append('#include "xm_riscv64.h"')
    lines.append('')

    for insn in mcinsns:
        if insn.name in _RV64_NAME_MAP:
            c_name = _RV64_NAME_MAP[insn.name]
            if c_name is None:
                continue
        else:
            c_name = _rv64_c_name(insn.name)
        operands = extract_operands(insn)

        params = []
        for op in operands:
            type_key = f'{op.kind}:{op.subtype}' if op.subtype else op.kind
            c_type = _RV64_PARAM_TYPES.get(type_key, 'int32_t')
            params.append(f'{c_type} {_c_param_name(op)}')

        sig = f'uint32_t {c_name}({", ".join(params)})'
        if not params:
            sig = f'uint32_t {c_name}(void)'

        enc_expr = _gen_riscv64_field_expr(insn.encoding, operands)

        lines.append(f'/* {insn.name} */')
        lines.append(sig + ' {')
        lines.extend(_gen_riscv64_return_lines(enc_expr))
        lines.append('}')
        lines.append('')

    return '\n'.join(lines)


