_RV64_REG_MAP = {
    **{f'x{i}': str(i) for i in range(32)},
    **{f'f{i}': str(i) for i in range(32)},
}

# Map ISA register names → C enum values
_X64_REG_MAP = {
    'rax': 'X64_RAX', 'rcx': 'X64_RCX', 'rdx': 'X64_RDX', 'rbx': 'X64_RBX',
    'rsp': 'X64_RSP', 'rbp': 'X64_RBP', 'rsi': 'X64_RSI', 'rdi': 'X64_RDI',
    'r8': 'X64_R8', 'r9': 'X64_R9', 'r10': 'X64_R10', 'r11': 'X64_R11',
    'r12': 'X64_R12', 'r13': 'X64_R13', 'r14': 'X64_R14', 'r15': 'X64_R15',
    'xmm0': 'X64_XMM0', 'xmm1': 'X64_XMM1', 'xmm2': 'X64_XMM2', 'xmm3': 'X64_XMM3',
    'xmm4': 'X64_XMM4', 'xmm5': 'X64_XMM5', 'xmm6': 'X64_XMM6', 'xmm7': 'X64_XMM7',
    'xmm8': 'X64_XMM8', 'xmm9': 'X64_XMM9', 'xmm10': 'X64_XMM10', 'xmm11': 'X64_XMM11',
    'xmm12': 'X64_XMM12', 'xmm13': 'X64_XMM13', 'xmm14': 'X64_XMM14', 'xmm15': 'X64_XMM15',
}

_A64_REG_MAP = {
    **{f'x{i}': f'A64_X{i}' for i in range(29)},
    'fp': 'A64_FP', 'lr': 'A64_LR', 'sp': 'A64_SP', 'xzr': 'A64_XZR',
}

def _detect_golden_reg_map(mcinsns: list[McInsn]) -> dict:
    """Detect which register map to use based on instruction prefix."""
    if mcinsns and mcinsns[0].name.startswith('arm64.'):
        return _A64_REG_MAP
    if mcinsns and mcinsns[0].name.startswith('riscv64.'):
        return _RV64_REG_MAP
    return _X64_REG_MAP

def _golden_arg_to_c(arg: str, op: OperandInfo, reg_map: dict) -> str:
    """Convert a golden-bytes argument to a C expression."""
    if arg in reg_map:
        return reg_map[arg]
    # Numeric immediate
    try:
        v = int(arg, 0)
        if op.subtype == 'u64':
            return f'(uint64_t) {v}ULL'
        if op.subtype == 'u32':
            return f'(uint32_t) {v}U'
        return str(v)
    except ValueError:
        return arg

def generate_golden_test(regclasses: list[RegClass], mcinsns: list[McInsn]) -> str:
    """Generate a C test file that verifies all golden-bytes entries."""
    arch = _detect_arch(mcinsns)
    reg_map = _detect_golden_reg_map(mcinsns)
    is_fixed32 = (arch in ('arm64', 'riscv64'))

    lines = []
    lines.append('/* AUTO-GENERATED by xisagen — DO NOT EDIT */')
    lines.append(f'/* Golden-bytes verification test for {arch} instruction encoding */')
    lines.append('')

    if arch == 'arm64':
        lines.append('#ifdef __aarch64__')
        lines.append('')
        lines.append('#include <stdio.h>')
        lines.append('#include <string.h>')
        lines.append('#include "xm_arm64.h"')
    elif arch == 'riscv64':
        # RISC-V golden test is cross-platform (encoder is pure math)
        lines.append('#include <stdio.h>')
        lines.append('#include <string.h>')
        lines.append('#include <stdint.h>')
        lines.append('')
        lines.append('/* Forward declarations for generated encoder functions */')
        for insn in mcinsns:
            if insn.name in _RV64_NAME_MAP:
                c_name = _RV64_NAME_MAP[insn.name]
                if c_name is None:
                    continue
            else:
                c_name = _rv64_c_name(insn.name)
            operands = extract_operands(insn)
            params = []
            for op in operands:
                type_key = f'{op.kind}:{op.subtype}' if op.subtype else op.kind
                c_type = _RV64_PARAM_TYPES.get(type_key, 'int32_t')
                params.append(f'{c_type} {_c_param_name(op)}')
            sig = f'uint32_t {c_name}({", ".join(params)})' if params else f'uint32_t {c_name}(void)'
            lines.append(f'{sig};')
    else:
        lines.append('#if defined(__x86_64__) || defined(_M_X64)')
        lines.append('')
        lines.append('#include <stdio.h>')
        lines.append('#include <string.h>')
        lines.append('#include "xm_x64.h"')

    lines.append('')
    lines.append('static int g_pass = 0;')
    lines.append('static int g_fail = 0;')
    lines.append('')

    if is_fixed32:
        # Fixed 32-bit: each function returns uint32_t, compare as 4-byte LE word
        lines.append('static void check_golden(const char *name, uint32_t got, const uint8_t *expected) {')
        lines.append('    uint32_t exp_word;')
        lines.append('    memcpy(&exp_word, expected, 4);')
        lines.append('    if (got != exp_word) {')
        lines.append('        fprintf(stderr, "FAIL: %s: expected 0x%08x, got 0x%08x\\n", name, exp_word, got);')
        lines.append('        g_fail++;')
        lines.append('    } else {')
        lines.append('        g_pass++;')
        lines.append('    }')
        lines.append('}')
    else:
        lines.append('static void check_golden(const char *name, X64Buf *buf, const uint8_t *expected, int len) {')
        lines.append('    if ((int) buf->pos != len || memcmp(buf->code, expected, (size_t) len) != 0) {')
        lines.append('        fprintf(stderr, "FAIL: %s: expected %d bytes [", name, len);')
        lines.append('        for (int i = 0; i < len; i++)')
        lines.append('            fprintf(stderr, "%s%02x", i ? " " : "", expected[i]);')
        lines.append('        fprintf(stderr, "], got %u bytes [", buf->pos);')
        lines.append('        for (uint32_t i = 0; i < buf->pos; i++)')
        lines.append('            fprintf(stderr, "%s%02x", i ? " " : "", buf->code[i]);')
        lines.append('        fprintf(stderr, "]\\n");')
        lines.append('        g_fail++;')
        lines.append('    } else {')
        lines.append('        g_pass++;')
        lines.append('    }')
        lines.append('}')

    lines.append('')
    lines.append('int main(void) {')

    if not is_fixed32:
        lines.append('    uint8_t mem[64];')
        lines.append('    X64Buf buf;')
        lines.append('')

    # Determine name map and c_name function
    if arch == 'arm64':
        name_map = _A64_NAME_MAP
        c_name_fn = _a64_c_name
    elif arch == 'riscv64':
        name_map = _RV64_NAME_MAP
        c_name_fn = _rv64_c_name
    else:
        name_map = _X64_NAME_MAP
        c_name_fn = _x64_c_name

    test_id = 0
    for insn in mcinsns:
        if not insn.golden_bytes:
            continue

        if insn.name in name_map:
            c_name = name_map.get(insn.name)
            if c_name is None:
                continue
        else:
            c_name = c_name_fn(insn.name)

        operands = extract_operands(insn)

        for regs, hex_str in insn.golden_bytes:
            expected_bytes = hex_str.split()
            nbytes = len(expected_bytes)

            # Build C arguments
            if is_fixed32:
                c_args = []
            else:
                c_args = ['&buf']
            for i, op in enumerate(operands):
                if i < len(regs):
                    c_args.append(_golden_arg_to_c(regs[i], op, reg_map))

            lines.append(f'    /* {insn.name}: {" ".join(regs)} → {hex_str} */')

            byte_list = ', '.join(f'0x{b}' for b in expected_bytes)

            if is_fixed32:
                lines.append('    {')
                lines.append(f'        static const uint8_t exp[] = {{{byte_list}}};')
                call_line = f'        check_golden("{insn.name} ({" ".join(regs)})", {c_name}({", ".join(c_args)}), exp);'
                if len(call_line) <= 100:
                    lines.append(call_line)
                else:
                    lines.append(f'        check_golden("{insn.name} ({" ".join(regs)})", {c_name}({", ".join(c_args)}),')
                    lines.append('                     exp);')
                lines.append('    }')
            else:
                lines.append(f'    x64_buf_init(&buf, mem, sizeof(mem));')
                lines.append(f'    {c_name}({", ".join(c_args)});')
                lines.append('    {')
                lines.append(f'        static const uint8_t exp[] = {{{byte_list}}};')
                call_line = f'        check_golden("{insn.name} ({" ".join(regs)})", &buf, exp, {nbytes});'
                if len(call_line) <= 100:
                    lines.append(call_line)
                else:
                    lines.append(f'        check_golden("{insn.name} ({" ".join(regs)})", &buf, exp,')
                    lines.append(f'                     {nbytes});')
                lines.append('    }')
            lines.append('')
            test_id += 1

    lines.append(f'    fprintf(stderr, "golden-bytes: %d passed, %d failed (of {test_id} total)\\n", g_pass, g_fail);')
    lines.append('    return g_fail > 0 ? 1 : 0;')
    lines.append('}')
    if arch == 'riscv64':
        pass  # no conditional compilation needed
    else:
        lines.append('')
        lines.append('#else')
        lines.append('int main(void) {')
        lines.append('    return 0;')
        lines.append('}')
        if arch == 'arm64':
            lines.append('#endif  // __aarch64__')
        else:
            lines.append('#endif  // __x86_64__ || _M_X64')
    lines.append('')
    return '\n'.join(lines)

# ============================================================
# L5: Typecheck — validate .isa internal consistency
# ============================================================

@dataclass
class IsaDiag:
    level: str   # "error" or "warn"
    insn: str
    msg: str

VALID_EXTERNAL_REFERENCES = {
    'llvm-mc',     # LLVM `llvm-mc` machine-code tool
    'gnu-as',      # GNU assembler (gas)
    'objdump',     # binary disassembler cross-check
    'riscv-spec',  # RISC-V official ISA specification
    'arm-arm',     # ARM Architecture Reference Manual
    'intel-sdm',   # Intel Software Developer's Manual
    'manual',      # hand-derived (must be reviewed)
}

def typecheck_isa(regclasses: list[RegClass], mcinsns: list[McInsn]) -> list[IsaDiag]:
    """Validate internal consistency of parsed .isa definitions."""
    diags = []

    # Build register name set from all regclasses
    all_regs = set()
    for rc in regclasses:
        for r in rc.regs:
            all_regs.add(r)

    # Build regclass name → RegClass map
    rc_map = {rc.name: rc for rc in regclasses}

    seen_names = set()
    for insn in mcinsns:
        # Duplicate name check
        if insn.name in seen_names:
            diags.append(IsaDiag('error', insn.name, 'duplicate mcinsn name'))
        seen_names.add(insn.name)

        # min/max bytes
        if insn.min_bytes <= 0:
            diags.append(IsaDiag('error', insn.name, ':min-bytes must be > 0'))
        if insn.max_bytes < insn.min_bytes:
            diags.append(IsaDiag('error', insn.name, ':max-bytes < :min-bytes'))

        # Operand extraction
        operands = extract_operands(insn)
        op_names = {op.name for op in operands}

        # Check encoding references valid operands
        if insn.encoding:
            enc_vars = _collect_variables(insn.encoding)
            for var in enc_vars:
                if var not in op_names:
                    diags.append(IsaDiag('error', insn.name,
                                         f'encoding references undefined operand {var}'))

        # :golden-bytes is the primary encoding contract — required for every mcinsn
        if not insn.golden_bytes:
            diags.append(IsaDiag('error', insn.name,
                                 ':golden-bytes is required (at least one entry)'))

        # :golden-asm is the disassembly contract — at least one canonical asm
        # row is required so future generated disasm / llvm-mc round-trip has a
        # grounded expected string. Row count may be smaller than :golden-bytes
        # because multiple encoding variants commonly share one canonical asm.
        if not insn.golden_asm:
            diags.append(IsaDiag('error', insn.name,
                                 ':golden-asm is required (at least one canonical row)'))
        elif len(insn.golden_asm) > len(insn.golden_bytes):
            diags.append(IsaDiag(
                'error', insn.name,
                f':golden-asm row count ({len(insn.golden_asm)}) must not '
                f'exceed :golden-bytes row count ({len(insn.golden_bytes)})'))

        # :external-reference points at the third-party source that produced the
        # golden values. Must be a documented reference so reviewers can cross-check.
        if not insn.external_ref:
            diags.append(IsaDiag('error', insn.name,
                                 ':external-reference is required'))
        elif insn.external_ref not in VALID_EXTERNAL_REFERENCES:
            diags.append(IsaDiag(
                'error', insn.name,
                f':external-reference {insn.external_ref!r} is not in the '
                f'documented set {sorted(VALID_EXTERNAL_REFERENCES)}'))

        # Golden bytes: validate hex string format
        for regs, hex_str in insn.golden_bytes:
            hex_bytes = hex_str.split()
            for hb in hex_bytes:
                if len(hb) != 2 or not all(c in '0123456789abcdefABCDEF' for c in hb):
                    diags.append(IsaDiag('error', insn.name,
                                         f'invalid hex byte "{hb}" in :golden-bytes'))
            # Check byte count vs min/max
            n_bytes = len(hex_bytes)
            if n_bytes < insn.min_bytes or n_bytes > insn.max_bytes:
                diags.append(IsaDiag('warn', insn.name,
                                     f'golden-bytes length {n_bytes} outside '
                                     f'[{insn.min_bytes}, {insn.max_bytes}]'))

        # Golden bytes: register names should be in regclass (if regs provided)
        for regs, _ in insn.golden_bytes:
            for r in regs:
                # Skip numeric immediate values
                try:
                    int(r, 0)
                    continue
                except ValueError:
                    pass
                if r.startswith('-'):
                    try:
                        int(r, 0)
                        continue
                    except ValueError:
                        pass
                if all_regs and r not in all_regs:
                    diags.append(IsaDiag('warn', insn.name,
                                         f'golden-bytes register "{r}" not in any regclass'))

    return diags

def _collect_variables(node: SExpr) -> set[str]:
    """Recursively collect all $variable names from an S-expression tree."""
    result = set()
    if isinstance(node, SAtom):
        if node.is_variable:
            result.add(node.value)
    elif isinstance(node, SList):
        for child in node.children:
            result.update(_collect_variables(child))
    return result

