def _test_isel_parser():
    print("  test_isel_parser...", end='', file=sys.stderr)
    isel_text = '''
# comment
ISEL(ADD,  x64,     GP_RR_COMM,  x64.add.rr)
ISEL(ADD,  arm64,   GP_RRR,      arm64.add.rrr)
ISEL(ADD,  riscv64, GP_RRR,      riscv64.add)
ISEL(DIV,  x64,     CUSTOM,      x64.idiv.r, "RAX:RDX sequence")
'''
    entries = parse_isel_def(isel_text)
    assert len(entries) == 4, f"expected 4, got {len(entries)}"
    assert entries[0].xm_op == 'ADD'
    assert entries[0].target == 'x64'
    assert entries[0].pattern == 'GP_RR_COMM'
    assert entries[3].notes == 'RAX:RDX sequence'

    # Validate against minimal ops
    ops_text = 'XM_OP(ADD, ARITH, 2, I64, COMMUTATIVE)\nXM_OP(DIV, ARITH, 2, I64, NONE)\n'
    ops = parse_ops_def(ops_text)
    errors = validate_isel(entries, ops)
    # DIV is missing arm64 and riscv64 entries
    assert any('DIV' in e and 'arm64' in e for e in errors)
    assert any('DIV' in e and 'riscv64' in e for e in errors)
    # ADD is complete
    assert not any('ADD' in e and 'missing' in e for e in errors)

    # Coverage report
    report = isel_coverage_report(entries, ops)
    assert 'isel coverage: 4 entries' in report
    print(" PASS", file=sys.stderr)

def _test_isa_parser():
    print("  test_isa_parser...", end='', file=sys.stderr)
    text = '''
    (define-regclass x64.gpr64
      :regs (rax rcx rdx rbx)
      :encoding-bits 4)
    (define-mcinsn x64.add.rr
      :operands       (($dst reg:gpr64) ($src reg:gpr64))
      :constraints    ((same $dst $src))
      :encoding       (rex.w 0x01 (modrm 0b11 $src $dst))
      :flags          ()
      :min-bytes      3
      :max-bytes      3
      :golden-bytes   (((rax rbx) "48 01 d8"))
      :golden-asm     (((rax rbx) "add rax, rbx"))
      :external-reference llvm-mc)
    '''
    tokens = tokenize_sexpr(text, 'test.isa')
    forms = parse_sexpr(tokens, 'test.isa')
    assert len(forms) == 2

    # Extract
    rc = extract_regclass(forms[0])
    assert rc.name == 'x64.gpr64'
    assert len(rc.regs) == 4
    assert rc.encoding_bits == 4

    insn = extract_mcinsn(forms[1])
    assert insn.name == 'x64.add.rr'
    assert insn.min_bytes == 3
    assert insn.max_bytes == 3
    assert len(insn.golden_bytes) == 1
    assert insn.golden_bytes[0] == (['rax', 'rbx'], '48 01 d8')
    assert insn.golden_asm[0] == (['rax', 'rbx'], 'add rax, rbx')
    assert insn.external_ref == 'llvm-mc'

    print(" PASS", file=sys.stderr)

def _test_emit_generator():
    print("  test_emit_generator...", end='', file=sys.stderr)
    # x64 emit
    text_x64 = '''
    (define-regclass x64.gpr64
      :regs (rax rcx rdx rbx rsp rbp rsi rdi r8 r9 r10 r11 r12 r13 r14 r15)
      :encoding-bits 4)
    (define-mcinsn x64.nop
      :operands () :constraints () :encoding (0x90) :flags ()
      :min-bytes 1 :max-bytes 1 :golden-bytes ((() "90")))
    (define-mcinsn x64.add.rr
      :operands (($dst reg:gpr64) ($src reg:gpr64))
      :constraints ((same $dst $src))
      :encoding (rex.w 0x01 (modrm 0b11 $src $dst))
      :flags () :min-bytes 3 :max-bytes 3
      :golden-bytes (((rax rbx) "48 01 d8")))
    '''
    rc, insns = load_isa_text(text_x64, 'test_x64')
    header = generate_emit_header('x64', rc, insns)
    assert 'xisa_emit_x64_nop' in header
    assert 'xisa_emit_x64_add_rr' in header
    assert 'static inline int' in header
    assert '0x48' in header  # REX.W
    assert '0x90' in header  # NOP opcode

    # arm64 emit
    text_arm64 = '''
    (define-regclass arm64.gpr64
      :regs (x0 x1 x2) :encoding-bits 5)
    (define-mcinsn arm64.add.rrr
      :operands (($rd reg:gpr64) ($rn reg:gpr64) ($rm reg:gpr64))
      :constraints () :flags () :min-bytes 4 :max-bytes 4
      :encoding (0x8b000000 (field 0 5 $rd) (field 5 5 $rn) (field 16 5 $rm))
      :golden-bytes (((x0 x1 x2) "20 00 02 8b")))
    '''
    rc, insns = load_isa_text(text_arm64, 'test_arm64')
    header = generate_emit_header('arm64', rc, insns)
    assert 'xisa_emit_arm64_add_rrr' in header
    assert '0x8b000000u' in header

    # riscv64 emit
    text_rv = '''
    (define-regclass riscv64.gpr :regs (x0 x1 x2) :encoding-bits 5)
    (define-mcinsn riscv64.add
      :operands (($rd reg:gpr) ($rs1 reg:gpr) ($rs2 reg:gpr))
      :constraints () :flags () :min-bytes 4 :max-bytes 4
      :encoding (r-type 0x33 0x0 0x00 $rd $rs1 $rs2)
      :golden-bytes (((x1 x2 x3) "b3 00 31 00")))
    '''
    rc, insns = load_isa_text(text_rv, 'test_rv')
    header = generate_emit_header('riscv64', rc, insns)
    assert 'xisa_emit_riscv64_add' in header
    assert 'r-type' not in header  # encoding format should not appear in output

    # riscv64impl — pure encoding functions returning uint32_t
    impl = generate_riscv64_impl(rc, insns)
    assert 'uint32_t rv64_add(' in impl
    assert 'return' in impl

    print(" PASS", file=sys.stderr)

def _test_typecheck():
    print("  test_typecheck...", end='', file=sys.stderr)

    # Valid definition — should produce no errors. All :golden-bytes /
    # :golden-asm / :external-reference fields are populated to match the
    # current .isa schema completeness invariant.
    text_ok = '''
    (define-regclass x64.gpr64
      :regs (rax rcx rdx rbx) :encoding-bits 4)
    (define-mcinsn x64.add.rr
      :operands (($dst reg:gpr64) ($src reg:gpr64))
      :constraints () :flags () :min-bytes 3 :max-bytes 3
      :encoding (rex.w 0x01 (modrm 0b11 $src $dst))
      :golden-bytes (((rax rbx) "48 01 d8"))
      :golden-asm (((rax rbx) "add rax, rbx"))
      :external-reference llvm-mc)
    '''
    rc, insns = load_isa_text(text_ok)
    diags = typecheck_isa(rc, insns)
    errors = [d for d in diags if d.level == 'error']
    assert len(errors) == 0, f"expected 0 errors, got {errors}"

    # Missing :golden-asm — should fail
    text_missing_asm = '''
    (define-mcinsn x64.no_asm
      :operands () :constraints () :flags ()
      :min-bytes 1 :max-bytes 1 :encoding (0x90)
      :golden-bytes ((() "90"))
      :external-reference llvm-mc)
    '''
    _, insns_a = load_isa_text(text_missing_asm)
    diags_a = typecheck_isa([], insns_a)
    asm_errs = [d for d in diags_a
                if d.level == 'error' and ':golden-asm' in d.msg]
    assert len(asm_errs) == 1, f"expected 1 :golden-asm error, got {asm_errs}"

    # Missing :external-reference — should fail
    text_missing_ext = '''
    (define-mcinsn x64.no_ext
      :operands () :constraints () :flags ()
      :min-bytes 1 :max-bytes 1 :encoding (0x90)
      :golden-bytes ((() "90"))
      :golden-asm ((() "nop")))
    '''
    _, insns_e = load_isa_text(text_missing_ext)
    diags_e = typecheck_isa([], insns_e)
    ext_errs = [d for d in diags_e
                if d.level == 'error' and ':external-reference' in d.msg]
    assert len(ext_errs) == 1, f"expected 1 :external-reference error, got {ext_errs}"

    # Bad :external-reference — should fail with accept-list message
    text_bad_ext = '''
    (define-mcinsn x64.bad_ext
      :operands () :constraints () :flags ()
      :min-bytes 1 :max-bytes 1 :encoding (0x90)
      :golden-bytes ((() "90"))
      :golden-asm ((() "nop"))
      :external-reference some-blog-post)
    '''
    _, insns_b = load_isa_text(text_bad_ext)
    diags_b = typecheck_isa([], insns_b)
    bad_ext_errs = [d for d in diags_b
                    if d.level == 'error' and 'documented set' in d.msg]
    assert len(bad_ext_errs) == 1, f"expected 1 bad-ref error, got {bad_ext_errs}"

    # :golden-asm row count > :golden-bytes row count — should fail
    text_too_many_asm = '''
    (define-mcinsn x64.too_many_asm
      :operands () :constraints () :flags ()
      :min-bytes 1 :max-bytes 1 :encoding (0x90)
      :golden-bytes ((() "90"))
      :golden-asm ((() "nop") (() "noop"))
      :external-reference llvm-mc)
    '''
    _, insns_t = load_isa_text(text_too_many_asm)
    diags_t = typecheck_isa([], insns_t)
    row_errs = [d for d in diags_t
                if d.level == 'error' and 'row count' in d.msg]
    assert len(row_errs) == 1, f"expected 1 row-count error, got {row_errs}"

    # Undefined operand in encoding
    text_bad_ref = '''
    (define-mcinsn x64.bad
      :operands (($dst reg:gpr64))
      :constraints () :flags () :min-bytes 3 :max-bytes 3
      :encoding (rex.w 0x01 (modrm 0b11 $ghost $dst))
      :golden-bytes (((rax) "48 01 c0")))
    '''
    _, insns2 = load_isa_text(text_bad_ref)
    diags2 = typecheck_isa([], insns2)
    errs2 = [d for d in diags2 if d.level == 'error' and 'undefined operand' in d.msg]
    assert len(errs2) == 1, f"expected 1 undefined-operand error, got {errs2}"

    # Duplicate name
    text_dup = '''
    (define-mcinsn x64.dup :operands () :constraints () :flags ()
      :min-bytes 1 :max-bytes 1 :encoding (0x90) :golden-bytes ((() "90")))
    (define-mcinsn x64.dup :operands () :constraints () :flags ()
      :min-bytes 1 :max-bytes 1 :encoding (0x90) :golden-bytes ((() "90")))
    '''
    _, insns3 = load_isa_text(text_dup)
    diags3 = typecheck_isa([], insns3)
    dup_errs = [d for d in diags3 if 'duplicate' in d.msg]
    assert len(dup_errs) == 1

    # max < min
    text_range = '''
    (define-mcinsn x64.bad_range :operands () :constraints () :flags ()
      :min-bytes 5 :max-bytes 3 :encoding (0x90) :golden-bytes ((() "90")))
    '''
    _, insns4 = load_isa_text(text_range)
    diags4 = typecheck_isa([], insns4)
    range_errs = [d for d in diags4 if d.level == 'error' and 'max-bytes' in d.msg]
    assert len(range_errs) == 1

    # Bad hex in golden-bytes
    text_hex = '''
    (define-mcinsn x64.bad_hex :operands () :constraints () :flags ()
      :min-bytes 1 :max-bytes 1 :encoding (0x90) :golden-bytes ((() "ZZ")))
    '''
    _, insns5 = load_isa_text(text_hex)
    diags5 = typecheck_isa([], insns5)
    hex_errs = [d for d in diags5 if d.level == 'error' and 'invalid hex' in d.msg]
    assert len(hex_errs) == 1

    print(" PASS", file=sys.stderr)

def _test_error_paths():
    print("  test_error_paths...", end='', file=sys.stderr)

    # Unterminated string
    try:
        tokenize_sexpr('"hello', 'test')
        assert False, "should have died"
    except SystemExit:
        pass

    # Unclosed paren
    try:
        tokens = tokenize_sexpr('(a b', 'test')
        parse_sexpr(tokens, 'test')
        assert False, "should have died"
    except SystemExit:
        pass

    # Unexpected )
    try:
        tokens = tokenize_sexpr(')', 'test')
        parse_sexpr(tokens, 'test')
        assert False, "should have died"
    except SystemExit:
        pass

    # Unexpected character
    try:
        tokenize_sexpr('`', 'test')
        assert False, "should have died"
    except SystemExit:
        pass

    print(" PASS", file=sys.stderr)


def main():
    if len(sys.argv) < 2:
        print(__doc__, file=sys.stderr)
        sys.exit(1)

    cmd = sys.argv[1]
    args = sys.argv[2:]

    commands = {
        'ops': cmd_ops,
        'xi-ops': cmd_xi_ops,
        'xi-lowering': cmd_xi_lowering,
        'xi-verify': cmd_xi_verify,
        'aot-rep': cmd_aot_rep,
        'aot-abi': cmd_aot_abi,
        'aot-layout': cmd_aot_layout,
        'helpers': cmd_helpers,
        'runtime-stubs': cmd_runtime_stubs,
        'isel': cmd_isel,
        'isa': cmd_isa,
        'x64impl': cmd_x64impl,
        'arm64impl': cmd_arm64impl,
        'riscv64impl': cmd_riscv64impl,
        'golden': cmd_golden,
        'dispatch-coverage': cmd_dispatch_coverage,
        'dispatch-meta': cmd_dispatch_meta,
        'dispatch-emit': cmd_dispatch_emit,
        'patch-ranges': cmd_patch_ranges,
        'disasm-check': cmd_disasm_check,
        'disasm': cmd_disasm,
        'disasm-test': cmd_disasm_test,
        'llvm-mc-check': cmd_llvm_mc_check,
        'random-diff': cmd_random_diff,
        'test': cmd_test,
    }

    if cmd not in commands:
        die(f"unknown command '{cmd}'. Available: {', '.join(commands)}")

    commands[cmd](args)


if __name__ == '__main__':
    main()
